import { Prediction } from '../api/client';

interface PredictionCardProps {
  prediction: Prediction;
  onClick?: (ticker: string) => void;
}

const MODEL_SIGNAL_DISCLAIMER =
  'Model Signal (not investment advice): This rating is generated by an automated statistical model and may be wrong. It is for educational/reference purposes only and is not a recommendation to buy or sell any security.';

function formatSignalLabel(signal?: string | null): string {
  const normalized = (signal || '').toLowerCase();
  if (normalized === 'buy' || normalized === 'strong_buy') return 'Bullish';
  if (normalized === 'sell' || normalized === 'avoid') return 'Bearish';
  return 'Neutral';
}

function formatSignalClass(signal?: string | null): 'buy' | 'sell' | 'hold' {
  const normalized = (signal || '').toLowerCase();
  if (normalized === 'buy' || normalized === 'strong_buy') return 'buy';
  if (normalized === 'sell' || normalized === 'avoid') return 'sell';
  return 'hold';
}

function buildTopDrivers(probability: string, probValue: number, horizon: string): string[] {
  const directionalSummary =
    probValue >= 0.55
      ? 'Recent trend/momentum inputs are supportive versus recent volatility.'
      : probValue <= 0.45
      ? 'Recent trend/momentum inputs are weaker and downside pressure is elevated.'
      : 'Trend, momentum, and volatility inputs are mixed with limited directional conviction.';

  return [
    `Upside probability: ${probability}% over the ${horizon} horizon.`,
    directionalSummary,
  ];
}

function PredictionCard({ prediction, onClick }: PredictionCardProps) {
  const { ticker, signal, prob_up, last_close, horizon } = prediction as any;

  const signalClass = formatSignalClass(signal);
  const signalLabel = formatSignalLabel(signal);
  const probability = prob_up !== null ? (prob_up * 100).toFixed(1) : '0.0';
  const probValue = prob_up ?? 0;
  const probClass = probValue >= 0.55 ? 'high' : probValue >= 0.45 ? 'medium' : 'low';
  const price = last_close?.toFixed(2) || '—';
  const horizonLabel = horizon || '1d';
  const topDrivers = buildTopDrivers(probability, probValue, horizonLabel);
  return (
    <div
      className={`prediction-card${onClick ? ' clickable' : ''}`}
      onClick={() => onClick && onClick(ticker)}
    >
      <div className="prediction-header">
        <span className="prediction-ticker">{ticker}</span>
        <div className="prediction-signal-stack">
          <span className={`prediction-signal ${signalClass}`}>{signalLabel}</span>
          <span className="prediction-signal-disclaimer">{MODEL_SIGNAL_DISCLAIMER}</span>
        </div>
      </div>
      <div className="prediction-stats">
        <div className="prediction-stat">
          <span className="prediction-stat-label">Last Price</span>
          <span className="prediction-stat-value">${price}</span>
        </div>
        <div className="prediction-stat">
          <span className="prediction-stat-label">Horizon</span>
          <span className="prediction-stat-value">{horizonLabel}</span>
        </div>
      </div>
      <div className="prediction-probability">
        <div className="prediction-stat">
          <span className="prediction-stat-label">Upside Probability</span>
          <span className="prediction-stat-value">{probability}%</span>
        </div>
        <div className="probability-bar-bg">
          <div
            className={`probability-bar ${probClass}`}
            style={{ width: `${probability}%` }}
          />
        </div>
      </div>
      <div className="prediction-drivers">
        <span className="prediction-drivers-label">Top Drivers (High-Level)</span>
        <ul className="prediction-drivers-list">
          {topDrivers.map((driver) => (
            <li key={driver}>{driver}</li>
          ))}
        </ul>
      </div>
    </div>
  );
}

export default PredictionCard;
